#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define AES_BLOCK_SIZE 16
#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 100

typedef struct {
    uint8_t key[32];
    uint8_t iv_state[AES_BLOCK_SIZE];
    uint32_t generation_counter;
    pthread_mutex_t lock;
} pdf_crypto_ctx_t;

typedef struct {
    time_t window_start;
    uint32_t request_count;
    pthread_mutex_t rate_lock;
} rate_limiter_t;

typedef struct {
    int status;
    uint8_t iv_used[AES_BLOCK_SIZE];
    uint8_t *encrypted_content;
    size_t content_len;
} pdf_result_t;

static rate_limiter_t g_limiter = {0};

int init_crypto_ctx(pdf_crypto_ctx_t *ctx, const uint8_t *master_key) {
    if (!ctx || !master_key) return -1;
    memcpy(ctx->key, master_key, 32);
    memset(ctx->iv_state, 0, AES_BLOCK_SIZE);
    ctx->generation_counter = 0;
    pthread_mutex_init(&ctx->lock, NULL);
    return 0;
}

void init_rate_limiter(void) {
    g_limiter.window_start = time(NULL);
    g_limiter.request_count = 0;
    pthread_mutex_init(&g_limiter.rate_lock, NULL);
}

int check_rate_limit(void) {
    pthread_mutex_lock(&g_limiter.rate_lock);
    time_t now = time(NULL);
    if (now - g_limiter.window_start >= RATE_LIMIT_WINDOW) {
        g_limiter.window_start = now;
        g_limiter.request_count = 0;
    }
    if (g_limiter.request_count >= MAX_REQUESTS_PER_WINDOW) {
        pthread_mutex_unlock(&g_limiter.rate_lock);
        return -1;
    }
    g_limiter.request_count++;
    pthread_mutex_unlock(&g_limiter.rate_lock);
    return 0;
}

/* Derives IV from context state. Called under lock. */
static void derive_iv(pdf_crypto_ctx_t *ctx, uint8_t *iv_out) {
    uint32_t counter = ctx->generation_counter;
    /* Mix counter into iv_state to produce unique IV */
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        iv_out[i] = ctx->iv_state[i] ^ ((counter >> ((i % 4) * 8)) & 0xFF);
    }
}

/* Advances the IV state after successful encryption */
static void advance_iv_state(pdf_crypto_ctx_t *ctx) {
    /* Increment iv_state as a 128-bit counter */
    for (int i = AES_BLOCK_SIZE - 1; i >= 0; i--) {
        if (++ctx->iv_state[i] != 0) break;
    }
    ctx->generation_counter++;
}

/* Simulated AES-CBC encryption */
static int aes_cbc_encrypt(const uint8_t *key, const uint8_t *iv,
                           const uint8_t *plaintext, size_t len,
                           uint8_t *ciphertext) {
    /* Placeholder: real implementation would use OpenSSL/libcrypto */
    if (!key || !iv || !plaintext || !ciphertext || len == 0) return -1;
    memcpy(ciphertext, plaintext, len);
    for (size_t i = 0; i < len; i++) {
        ciphertext[i] ^= iv[i % AES_BLOCK_SIZE] ^ key[i % 32];
    }
    return 0;
}

/* Core PDF content encryption with retry logic */
pdf_result_t encrypt_pdf_content(pdf_crypto_ctx_t *ctx,
                                  const uint8_t *content,
                                  size_t content_len) {
    pdf_result_t result = {0};
    result.encrypted_content = NULL;
    result.status = -1;

    /* Validate inputs before use */
    if (!ctx || !content || content_len == 0) {
        return result;
    }

    uint8_t iv[AES_BLOCK_SIZE];
    int attempt = 0;
    int encrypted = 0;

    while (attempt < MAX_RETRIES && !encrypted) {
        if (check_rate_limit() != 0) {
            attempt++;
            struct timespec ts = {0, 100000000L}; /* 100ms backoff */
            nanosleep(&ts, NULL);
            continue;
        }

        /* Derive IV inside retry loop under lock - ensures fresh IV each attempt */
        pthread_mutex_lock(&ctx->lock);
        derive_iv(ctx, iv);
        advance_iv_state(ctx);
        pthread_mutex_unlock(&ctx->lock);

        size_t padded_len = ((content_len + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE) * AES_BLOCK_SIZE;
        uint8_t *output = (uint8_t *)malloc(padded_len);
        if (!output) {
            attempt++;
            continue;
        }

        uint8_t *padded_input = (uint8_t *)calloc(1, padded_len);
        if (!padded_input) {
            free(output);
            attempt++;
            continue;
        }
        memcpy(padded_input, content, content_len);

        /* Encrypt using the derived IV */
        if (aes_cbc_encrypt(ctx->key, iv, padded_input, padded_len, output) == 0) {
            encrypted = 1;
            result.encrypted_content = output;
            result.content_len = padded_len;
            memcpy(result.iv_used, iv, AES_BLOCK_SIZE);
            result.status = 0;
        } else {
            free(output);
            attempt++;
        }
        free(padded_input);
    }

    return result;
}

/* Generate encrypted PDF document */
int generate_encrypted_pdf(pdf_crypto_ctx_t *ctx,
                           const char *title,
                           const uint8_t *body,
                           size_t body_len,
                           const char *output_path) {
    if (!ctx || !title || !body || !output_path) return -1;
    if (body_len == 0 || strlen(title) == 0) return -1;

    /* Encrypt the body content */
    pdf_result_t body_enc = encrypt_pdf_content(ctx, body, body_len);
    if (body_enc.status != 0) return -1;

    /* Encrypt the title as metadata */
    pdf_result_t title_enc = encrypt_pdf_content(ctx, (const uint8_t *)title, strlen(title));
    if (title_enc.status != 0) {
        free(body_enc.encrypted_content);
        return -1;
    }

    FILE *fp = fopen(output_path, "wb");
    if (!fp) {
        free(body_enc.encrypted_content);
        free(title_enc.encrypted_content);
        return -1;
    }

    /* Write PDF header with encryption metadata */
    fprintf(fp, "%%PDF-1.7\n");
    fprintf(fp, "%%Encrypted: AES-256-CBC\n");
    fwrite(body_enc.iv_used, 1, AES_BLOCK_SIZE, fp);
    fwrite(body_enc.encrypted_content, 1, body_enc.content_len, fp);
    fwrite(title_enc.iv_used, 1, AES_BLOCK_SIZE, fp);
    fwrite(title_enc.encrypted_content, 1, title_enc.content_len, fp);
    fprintf(fp, "\n%%%%EOF\n");

    fclose(fp);
    free(body_enc.encrypted_content);
    free(title_enc.encrypted_content);
    return 0;
}
